css:
.electric-pulse {
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(34, 0, 255, 0.831) 0%,
    rgba(0, 22, 65, 0.6) 50%,
    rgba(0, 0, 50, 0.4) 100%
  );
  filter: url(#pulse-texture);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.electric-pulse::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0);
  pointer-events: none;
}
